mapper.select:
SELECT COUNT(*) FROM devices d LEFT JOIN warehouse_areas wa ON wa.id = d.area_id LEFT JOIN ( SELECT device_id, MAX(alert_level) as highest_alert_level, COUNT(*) as alert_count FROM alerts WHERE status IN ('UNHANDLED', 'HANDLING') GROUP BY device_id ) ua ON ua.device_id = d.id WHERE d.enabled = 1
AND d.area_id = #{areaId}
AND ( (#{online} = 1 OR #{online} = true OR #{online} = 'true') AND d.online_status = 1 OR (#{online} = 0 OR #{online} = false OR #{online} = 'false') AND d.online_status = 0 )
AND ( ((#{alarming} = 1 OR #{alarming} = true OR #{alarming} = 'true') AND ua.alert_count IS NOT NULL) OR ((#{alarming} = 0 OR #{alarming} = false OR #{alarming} = 'false') AND ua.alert_count IS NULL) )
AND d.device_type = #{deviceType}
AND (d.device_code LIKE CONCAT('%', #{keyword}, '%') OR d.device_name LIKE CONCAT('%', #{keyword}, '%'))

WITH latest_data AS ( SELECT sd.device_id, sd.temperature, sd.humidity, sd.data_time, ROW_NUMBER() OVER (PARTITION BY sd.device_id ORDER BY sd.data_time DESC) rn FROM sensor_data sd WHERE sd.data_time >= DATE_SUB(NOW(), INTERVAL 24 HOUR) ), unresolved_alerts AS ( SELECT device_id, MAX(alert_level) as highest_alert_level, COUNT(*) as alert_count FROM alerts WHERE status IN ('UNHANDLED', 'HANDLING') GROUP BY device_id ) SELECT d.id, d.device_code as deviceCode, d.device_name as deviceName, d.device_type as deviceType, d.area_id as areaId, wa.area_name as areaName, wa.area_name as areaPath, d.online_status as online, d.last_seen_time as lastSeenTime, ld.temperature as latestTemp, ld.humidity as latestHumi, ld.data_time as latestDataTime, IFNULL(ua.alert_count > 0, 0) as hasUnresolvedAlert, ua.highest_alert_level as highestAlertLevel, d.threshold_mode as thresholdMode, COALESCE(d.temperature_threshold_min, wa.temperature_threshold_min) as temperatureThresholdMin, COALESCE(d.temperature_threshold_max, wa.temperature_threshold_max) as temperatureThresholdMax, COALESCE(d.humidity_threshold_min, wa.humidity_threshold_min) as humidityThresholdMin, COALESCE(d.humidity_threshold_max, wa.humidity_threshold_max) as humidityThresholdMax FROM devices d LEFT JOIN latest_data ld ON ld.device_id = d.id AND ld.rn = 1 LEFT JOIN unresolved_alerts ua ON ua.device_id = d.id LEFT JOIN warehouse_areas wa ON wa.id = d.area_id WHERE d.enabled = 1
AND d.area_id = #{areaId}
AND ( (#{online} = 1 OR #{online} = true OR #{online} = 'true') AND d.online_status = 1 OR (#{online} = 0 OR #{online} = false OR #{online} = 'false') AND d.online_status = 0 )
AND ( ((#{alarming} = 1 OR #{alarming} = true OR #{alarming} = 'true') AND ua.alert_count IS NOT NULL) OR ((#{alarming} = 0 OR #{alarming} = false OR #{alarming} = 'false') AND ua.alert_count IS NULL) )
AND d.device_type = #{deviceType}
AND (d.device_code LIKE CONCAT('%', #{keyword}, '%') OR d.device_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.id DESC LIMIT #{limit} OFFSET #{offset}
